<?php require_once '../includes/functions.php';require_staff();$pdo=db();$quizId=(int)($_GET['quiz_id']??$_POST['quiz_id']??0);[$access,$params]=quiz_access_sql('q');$s=$pdo->prepare("SELECT q.* FROM quizzes q WHERE q.id=? AND $access");$s->execute(array_merge([$quizId],$params));$quiz=$s->fetch();if(!$quiz){http_response_code(404);exit('Quiz not found or access denied.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');if($action==='add'){$text=post('question_text');$options=array_map('trim',$_POST['options']??[]);$correct=(int)($_POST['correct']??-1);if(!$text||count($options)!==4||in_array('',$options,true)||$correct<0||$correct>3)$errors[]='Enter a question, four options, and choose the correct answer.';else{$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO questions(quiz_id,question_text) VALUES(?,?)');$s->execute([$quizId,$text]);$qid=$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO options(question_id,option_text,is_correct) VALUES(?,?,?)');foreach($options as $i=>$o)$s->execute([$qid,$o,$i===$correct]);$pdo->commit();flash('success','Question added.');redirect("questions.php?quiz_id=$quizId");}catch(Throwable $e){$pdo->rollBack();throw $e;}}}if($action==='delete'){$s=$pdo->prepare('DELETE FROM questions WHERE id=? AND quiz_id=?');$s->execute([(int)$_POST['id'],$quizId]);flash('success','Question deleted.');redirect("questions.php?quiz_id=$quizId");}}
$s=$pdo->prepare('SELECT q.id,q.question_text,o.id option_id,o.option_text,o.is_correct FROM questions q JOIN options o ON o.question_id=q.id WHERE q.quiz_id=? ORDER BY q.id,o.id');$s->execute([$quizId]);$rows=$s->fetchAll();$questions=[];foreach($rows as $r){$questions[$r['id']]['text']=$r['question_text'];$questions[$r['id']]['options'][]=$r;}$pageTitle='Manage Questions';require '../includes/header.php';?>
<a href="quizzes.php">← Back to quizzes</a><h1><?=e($quiz['title'])?></h1><div class="split"><form class="form-card wide" method="post"><h2>Add Question</h2><?php foreach($errors as $x):?><p class="error"><?=e($x)?></p><?php endforeach;?><?=csrf_field()?><input type="hidden" name="quiz_id" value="<?=$quizId?>"><input type="hidden" name="action" value="add"><label>Question</label><textarea name="question_text" required></textarea><?php for($i=0;$i<4;$i++):?><label>Option <?=chr(65+$i)?></label><div style="display:flex;gap:10px;align-items:center"><input style="width:auto" type="radio" name="correct" value="<?=$i?>" required title="Correct answer"><input name="options[]" required></div><?php endfor;?><p class="muted">Select the radio button beside the correct option.</p><button>Add Question</button></form><div class="card"><h2>Summary</h2><p><strong><?=count($questions)?></strong> questions added.</p><p>Status: <?=$quiz['is_published']?'Published':'Draft'?></p><a class="button secondary" href="quizzes.php">Finish</a></div></div>
<h2>Existing Questions</h2><?php $number=0;foreach($questions as $questionId=>$q):$number++;?><article class="card"><h3><?=$number?>. <?=e($q['text'])?></h3><ol type="A"><?php foreach($q['options'] as $o):?><li><?=e($o['option_text'])?> <?=$o['is_correct']?'✓':''?></li><?php endforeach;?></ol><form method="post"><?=csrf_field()?><input type="hidden" name="quiz_id" value="<?=$quizId?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$questionId?>"><button class="button small danger" data-confirm="Delete this question?">Delete</button></form></article><br><?php endforeach;?>
<?php require '../includes/footer.php';?>
